-- Create grid_references table
CREATE TABLE grid_references (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL,
  category TEXT NOT NULL,
  canvas_width INTEGER NOT NULL,
  canvas_height INTEGER NOT NULL,
  reference_image_url TEXT NOT NULL,
  grid_config JSONB NOT NULL,
  analysis JSONB NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- RLS Policies
ALTER TABLE grid_references ENABLE ROW LEVEL SECURITY;

-- Allow public read access to grid_references
CREATE POLICY "Public profiles are viewable by everyone."
  ON grid_references FOR SELECT
  USING ( true );

-- Insert seed data into grid_references

-- Create storage bucket for grid references

CREATE POLICY "Public Read Access" ON storage.objects FOR SELECT USING (bucket_id = 'grid-references');
